import{c as e,S as l,j as r,m as a}from"./chunks/framework.8aa1YH_s.js";const u=JSON.parse('{"title":"İçindekiler","description":"","frontmatter":{},"headers":[],"relativePath":"İçindekiler.md","filePath":"İçindekiler.md"}'),n={name:"İçindekiler.md"};function s(m,i,t,o,k,d){return l(),r("div",null,[...i[0]||(i[0]=[a('<h1 id="icindekiler" tabindex="-1">İçindekiler <a class="header-anchor" href="#icindekiler" aria-label="Permalink to “İçindekiler”">​</a></h1><p>Bu rehber, <strong>Prof. Dr. Muharrem Ergin</strong>&#39;in akademik sistematiği esas alınarak hazırlanmış, Türk dil bilgisinin tüm yapı taşlarını içeren 19 bölümlük kapsamlı bir başucu serisidir.</p><hr><h3 id="🌐-i-bolum-dilin-dogası-ve-tarihi-gelisimi" tabindex="-1">🌐 I. Bölüm: Dilin Doğası ve Tarihî Gelişimi <a class="header-anchor" href="#🌐-i-bolum-dilin-dogası-ve-tarihi-gelisimi" aria-label="Permalink to “🌐 I. Bölüm: Dilin Doğası ve Tarihî Gelişimi”">​</a></h3><ul><li><strong>1. Dil Nedir ve Dünya Dilleri Arasındaki Yeri:</strong> Dil aileleri, Ural-Altay dil grubu, yapı ve köken bakımından diller, konuşma ve yazı dili kavramları.</li><li><strong>2. Türk Yazı Dilinin Tarihî Gelişimi ve Kolları:</strong> Eski Türkçe, Kuzey-Doğu Türkçesi, Batı Türkçesi ve modern Türkiye Türkçesi. <ul><li><em>Görsel Şema:</em> <code>![Türk Yazı Dilinin Gelişim Şeması](../görseller/ESKİ_TÜRKÇE.png)</code></li></ul></li></ul><hr><h3 id="🗣️-ii-bolum-ses-bilgisi-fonetik" tabindex="-1">🗣️ II. Bölüm: Ses Bilgisi (Fonetik) <a class="header-anchor" href="#🗣️-ii-bolum-ses-bilgisi-fonetik" aria-label="Permalink to “🗣️ II. Bölüm: Ses Bilgisi (Fonetik)”">​</a></h3><ul><li><strong>3. Ses Bilgisi (Fonetik) ve Seslerin Mahiyeti:</strong> Dilin en küçük birimi olan sesin oluşumu, harf kavramı ve Türkçenin genel ses özellikleri.</li><li><strong>4. Türkçedeki Vokaller (Ünlüler) ve Tasnifi:</strong> Ünlülerin çıkış yerlerine ve niteliklerine (kalın-ince, düz-yuvarlak, geniş-dar) göre sınıflandırılması.</li><li><strong>5. Türkçede Ünlü (Vokal) Uyumları ve Kuralları:</strong> Büyük Ünlü Uyumu (Kalınlık-İncelik) ve Küçük Ünlü Uyumu (Düzlük-Yuvarlaklık) kuralları ile istisnaları.</li><li><strong>6. Konsonantlar (Ünsüzler) ve Sınıflandırılması:</strong> Ünsüzlerin tonlu/tonsuz (sert/yumuşak) ve çıkış noktalarına göre karakteristiği.</li><li><strong>7. Türkçedeki Ses Hadiseleri (Ses Olayları):</strong> Ses düşmesi, türemesi, benzeşmesi, yumuşaması ve ünlü daralması gibi fonetik değişimler.</li></ul><hr><h3 id="🏗️-iii-bolum-sekil-bilgisi-morfoloji" tabindex="-1">🏗️ III. Bölüm: Şekil Bilgisi (Morfoloji) <a class="header-anchor" href="#🏗️-iii-bolum-sekil-bilgisi-morfoloji" aria-label="Permalink to “🏗️ III. Bölüm: Şekil Bilgisi (Morfoloji)”">​</a></h3><ul><li><strong>8. Şekil Bilgisi (Morfoloji) - Kelime Yapısı, Kökler ve Gövdeler:</strong> İsim ve fiil kökleri, ortak ve sesteş kök ayrımları, gövde mekanizması.</li><li><strong>9. Şekil Bilgisi - Eklerin Dünyası ve Yapım Ekleri:</strong> İsimden isim, isimden fiil, fiilden isim ve fiilden fiil türetme ekleri. <ul><li><em>Görsel Şema:</em> <code>![Yapım Ekleri Sınıflandırma Şeması](../görseller/YAPIM_EKLERİ.png)</code></li></ul></li><li><strong>10. Şekil Bilgisi - İsim Çekim Ekleri:</strong> Çokluk (çoğul) eki, iyelik ekleri, ilgi eki ve isim hal (durum) ekleri.</li><li><strong>11. Şekil Bilgisi - Fiil Çekim Ekleri (Kip, Zaman ve Şahıs):</strong> Haber (bildirme) kipleri, dilek (tasarlama) kipleri ve şahıs ekleri hiyerarşisi.</li></ul><hr><h3 id="🎯-iv-bolum-kelime-turleri" tabindex="-1">🎯 IV. Bölüm: Kelime Türleri <a class="header-anchor" href="#🎯-iv-bolum-kelime-turleri" aria-label="Permalink to “🎯 IV. Bölüm: Kelime Türleri”">​</a></h3><ul><li><strong>12. Kelime Türleri - İsimler ve İsim Tamlamaları:</strong> Varlıklara verilişlerine, sayılarına ve maddelerine göre isimler; Belirtili, belirtisiz ve zincirleme isim tamlamaları. <ul><li><em>Görsel Şema:</em> <code>![İsim Tamlamaları Yapı Şeması](../görseller/İSİM_TAMLAMALARI.png)</code></li></ul></li><li><strong>13. Kelime Türleri - Sıfatlar (Ön Adlar):</strong> Niteleme sıfatları, unvanlar, belirtme sıfatları (işaret, sayı, belgisiz, soru) ve adlaşmış sıfat.</li><li><strong>14. Kelime Türleri - Zamirler (Adıllar):</strong> Kelime halindeki (şahıs, işaret, belgisiz, soru) ve ek halindeki (iyelik, ilgi) zamirler.</li><li><strong>15. Kelime Türleri - Zarflar (Belirteçler):</strong> Durum, zaman, miktar (derecelendirme), yer-yön ve soru zarfları.</li><li><strong>16. Kelime Türleri - Edatlar, Bağlaçlar ve Ünlemler:</strong> Tek başına anlamı olmayan, cümle içinde köprü, bağ veya duygu tonu kuran yardımcı unsurlar.</li><li><strong>17. Kelime Türleri - Fiiller ve Fiil Çatıları:</strong> Eylemler; öznesine göre (etken, edilgen, dönüşlü, işteş) ve nesnesine göre (geçişli, geçişsiz, oldurgan, ettirgen) çatılar. <ul><li><em>Görsel Şema:</em> <code>![Fiil Çatıları İlişki Şeması](../görseller/FİİL_ÇATILARI.png)</code></li></ul></li></ul><hr><h3 id="📐-v-bolum-cumle-bilgisi-sentaks" tabindex="-1">📐 V. Bölüm: Cümle Bilgisi (Sentaks) <a class="header-anchor" href="#📐-v-bolum-cumle-bilgisi-sentaks" aria-label="Permalink to “📐 V. Bölüm: Cümle Bilgisi (Sentaks)”">​</a></h3><ul><li><strong>18. Cümle Bilgisi (Sentaks) - Cümlenin Ögeleri:</strong> Asli ögeler (yüklem, özne) ve yardımcı ögeler (nesne, yer tamlayıcısı, zarf tamlayıcısı).</li><li><strong>19. (FİNAL) Cümle Türleri ve Yapısal Analiz:</strong> Yüklemin türüne, yerine, anlamına ve yapısına (basit, birleşik, sıralı, bağlı) göre cümle mimarisi.</li></ul>',17)])])}const h=e(n,[["render",s]]);export{u as __pageData,h as default};
